import React from 'react';
import {FormHelperText} from "@mui/material";

interface ICoreFormHelperTextProps {
    errorMessage: string | undefined;
}

const CoreFormHelperText = ({errorMessage}: ICoreFormHelperTextProps) => {
    return (
        <FormHelperText
            sx={{color: "var(--color-danger-text)", marginLeft: "16px !important"}}
        >
            {errorMessage}
        </FormHelperText>
    );
};

export default CoreFormHelperText;
