import React from "react";
import { MyFormControl } from "./styled";

interface CoreFormControlProps {
  horizontalMargin?: boolean;
  verticalMargin?: boolean;
  error?: boolean;
  children?: any;
}

const CoreFormControl = ({
  verticalMargin,
  horizontalMargin,
  error,
  children,
}: CoreFormControlProps) => {
  return (
    <MyFormControl
      fullWidth
      error={error}
      horizontalMargin={horizontalMargin}
      verticalMargin={verticalMargin}
    >
      {children}
    </MyFormControl>
  );
};

export default CoreFormControl;
